<?php
namespace App\Models;use App\Enums\TechnicianAssignmentStatus;use Illuminate\Database\Eloquent\Factories\HasFactory;use Illuminate\Database\Eloquent\Model;
class TechnicianAssignment extends Model{use HasFactory;protected $fillable=['service_order_id','technician_id','assigned_at','accepted_at','rejected_at','started_at','completed_at','status','assigned_by','note'];protected $casts=['status'=>TechnicianAssignmentStatus::class,'assigned_at'=>'datetime','accepted_at'=>'datetime','rejected_at'=>'datetime','started_at'=>'datetime','completed_at'=>'datetime'];public function serviceOrder(){return $this->belongsTo(ServiceOrder::class);}public function technician(){return $this->belongsTo(Technician::class);}public function assigner(){return $this->belongsTo(User::class,'assigned_by');}}
